export type TranslationKey = keyof typeof ko
export const catalogs = { 'ko-KR': ko, 'en-US': en } as const

export function resolveLocale(preference: LocalePreference, systemLocales?: readonly string[]): ResolvedLocale {
  if (preference === 'ko-KR' || preference === 'en-US') return preference
  const locales = systemLocales ?? (typeof navigator === 'undefined' ? [] : navigator.languages?.length ? navigator.languages : [navigator.language])
  for (const locale of locales) {
    const language = locale.toLowerCase().split('-')[0]
    if (language === 'ko') return 'ko-KR'
    if (language === 'en') return 'en-US'
  }
  return 'en-US'
}

export function translate(locale: ResolvedLocale, key: TranslationKey, values: TranslationValues = {}): string {
  const template = catalogs[locale][key] ?? catalogs['en-US'][key]
  return template.replace(/\{([A-Za-z0-9_]+)\}/g, (match, name: string) => String(values[name] ?? match))
}

const errorKeys: Record<string, TranslationKey> = {
  invalid_argument: 'errors.validation', validation_failed: 'errors.validation', invalid_preferences: 'errors.preferencesInvalid',
  unauthorized: 'errors.unauthorized', authentication_required: 'errors.unauthorized', forbidden: 'errors.forbidden',
  not_found: 'errors.notFound', conflict: 'errors.conflict', unsupported_archive_format: 'errors.unsupportedArchiveFormat',
  archive_index_unavailable: 'errors.archiveIndexUnavailable', generation_capability_mismatch: 'errors.generationCapabilityMismatch',
  storage_binding_failed: 'errors.server', plugin_registry_unavailable: 'errors.server',
  preferences_invalid: 'errors.preferencesInvalid', preferences_unavailable: 'errors.preferencesUnavailable',
  archive_index_unsupported_format: 'errors.archiveIndexUnsupportedFormat', archive_index_invalid_pagination: 'errors.archiveIndexInvalidPagination', archive_index_invalid_cursor: 'errors.archiveIndexInvalidCursor',
  export_invalid_request: 'errors.validation', export_unsupported_format: 'errors.unsupportedArchiveFormat', export_unavailable: 'errors.server', export_not_found: 'errors.notFound', export_state_conflict: 'errors.conflict', export_capacity: 'errors.server', export_unsupported: 'errors.unsupportedArchiveFormat', export_timeout: 'errors.server', export_failed: 'errors.server',
  integrity_unavailable: 'errors.server', integrity_capacity: 'errors.server', integrity_job_conflict: 'errors.conflict', integrity_active_recording: 'errors.conflict', integrity_job_not_found: 'errors.notFound', integrity_cancel_invalid_request: 'errors.validation', integrity_cancel_failed: 'errors.server', recording_manager_unavailable: 'errors.server',
}

export function localizedAPIError(locale: ResolvedLocale, code?: string, status?: number): string {
  const known = code ? errorKeys[code.toLowerCase()] : undefined
  if (known) return translate(locale, known)
  if (status === 0) return translate(locale, 'errors.network')
  if (status === 400 || status === 422) return translate(locale, 'errors.validation')
  if (status === 401) return translate(locale, 'errors.unauthorized')
  if (status === 403) return translate(locale, 'errors.forbidden')
  if (status === 404) return translate(locale, 'errors.notFound')
  if (status === 409) return translate(locale, 'errors.conflict')
  if (status !== undefined && status >= 500) return translate(locale, 'errors.server')
  return translate(locale, 'errors.generic')
}
